<div class="page-head"><div><h1>Feeds</h1><p>XML feeds για συγκριτικά τιμών και marketplaces. Περιλαμβάνουν μόνο ενεργά προϊόντα.</p></div><div class="actions"><?php if (ShopAdmin::feature('feeds_custom')): ?><a class="btn btn-primary" href="/admin/feeds/new"><?= icon('plus') ?>Custom feed</a><?php endif; ?></div></div>
<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Feed</th><th>Τύπος</th><th>URL</th><th>Συχνότητα</th><th class="r">Προϊόντα</th><th>Τελευταία δημιουργία</th><th>Κατάσταση</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $f): ?><tr><td><a class="title" href="/admin/feeds/<?= $f['id'] ?>"><?= e($f['name']) ?></a></td><td><?= e(Feeds::TYPES[$f['type']] ?? $f['type']) ?></td>
<td><?php if ($f['allowed'] && $f['status'] === 'active'): ?><a class="mono" href="<?= e($f['url']) ?>" target="_blank" rel="noopener" style="font-size:12px"><?= e(parse_url($f['url'], PHP_URL_PATH)) ?></a> <button class="btn btn-sm btn-ghost" type="button" data-copy="<?= e($f['url']) ?>">Αντιγραφή</button><?php else: ?><span class="muted">—</span><?php endif; ?></td>
<td><?= e(Feeds::FREQ[$f['frequency']] ?? '') ?></td><td class="r num"><?= $f['last_count'] ?? '—' ?></td><td class="num"><?= fmt_date($f['last_generated_at'], true) ?></td>
<td><?= !$f['allowed'] ? '<span class="badge b-muted">Εκτός πακέτου</span>' : status_badge($f['status']) ?></td>
<td class="actions"><?php if ($f['allowed']): ?><form method="post" action="/admin/feeds/<?= $f['id'] ?>/regenerate" style="display:inline"><?= csrf_field() ?><button class="btn btn-sm"><?= icon('refresh') ?></button></form> <a class="btn btn-sm" href="/admin/feeds/<?= $f['id'] ?>"><?= icon('edit') ?></a><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div></div>
<div class="card"><div class="hd"><h2>Ιστορικό δημιουργίας</h2></div><div class="bd flush table-wrap"><table class="table"><tbody><?php foreach ($logs as $l): ?><tr><td class="num"><?= fmt_date($l['created_at'], true) ?></td><td><?= e($l['name']) ?></td><td><?= status_badge($l['status']) ?></td><td class="num"><?= (int) $l['items'] ?> προϊόντα</td><td class="num"><?= (int) $l['duration_ms'] ?> ms</td><td class="sub"><?= e($l['message']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
